-- AI Opportunities directory: large expansion (100 new platforms) plus guide fill for existing ones.
-- Run 00015 first. Safe to run more than once.
-- RULES: every new row starts as "under_review" with Kenya "unknown" unless a Kenya-based source says otherwise.
-- last_verified is left empty: staff set it after checking each official site in /admin/ai.
-- Guide fields only fill EMPTY values, so researched notes from earlier migrations are never overwritten.
-- Pay, payout methods and compensation are deliberately left unfilled unless a platform publishes them.

on conflict (slug) do nothing;

  select id from public.ai_platforms
  on conflict (platform_id) do nothing;

create temp table _tpl (typ text primary key, avail text, ov text, eq text[], sk text[], reg text[], assess text, anotes text, earn text, pay text, steps text[], mist text[], rec text[]);

create temp table _plat (slug text primary key, name text, typ text, descr text, url text, reg text, pays text, min_age int, kenya_note text, earn_override text);

update public.ai_platform_guides g set
  accepting_registrations = case when g.accepting_registrations = 'unknown' then pl.reg else g.accepting_registrations end,
  has_projects = case when g.has_projects = 'unknown' then 'varies' else g.has_projects end,
  pays_in_kenya = case when g.pays_in_kenya = 'unknown' then pl.pays else g.pays_in_kenya end,
  country_eligibility = coalesce(g.country_eligibility, 'Not independently verified. Check the official eligibility pages.' || coalesce(pl.kenya_note, '')),
  min_age = coalesce(g.min_age, pl.min_age),
  required_equipment = case when cardinality(g.required_equipment) = 0 then t.eq else g.required_equipment end,
  required_skills = case when cardinality(g.required_skills) = 0 then t.sk else g.required_skills end,
  registration_requirements = case when cardinality(g.registration_requirements) = 0 then t.reg else g.registration_requirements end,
  assessment_requirements = coalesce(g.assessment_requirements, t.assess),
  application_availability = coalesce(g.application_availability, t.avail),
  overview = coalesce(g.overview, pl.descr || ' ' || t.ov),
  eligibility_notes = coalesce(g.eligibility_notes, 'Country availability, age limits and identity rules for ' || pl.name || ' were not independently verified. Read the platform''s own eligibility and terms pages before you register, and use your real name and your real location.'),
  account_steps = case when cardinality(g.account_steps) = 0 then t.steps else g.account_steps end,
  assessment_notes = coalesce(g.assessment_notes, t.anotes),
  earning_notes = coalesce(g.earning_notes, pl.earn_override, t.earn),
  payments_notes = coalesce(g.payments_notes, t.pay),
  common_mistakes = case when cardinality(g.common_mistakes) = 0 then t.mist else g.common_mistakes end,
  recommendations = case when cardinality(g.recommendations) = 0 then t.rec else g.recommendations end,
  restriction_notes = coalesce(g.restriction_notes, 'No country restriction was independently verified. Not independently verified by Savanna. Confirm on the official site before you spend time.'),
  resources = case when g.resources = '[]'::jsonb and pl.url is not null then jsonb_build_array(jsonb_build_object('label', 'Official website', 'url', pl.url)) else g.resources end,
  sources = case when g.sources = '[]'::jsonb and pl.url is not null then jsonb_build_array(jsonb_build_object('label', pl.name || ' official website', 'url', pl.url)) else g.sources end,
  updated_at = now()
from public.ai_platforms p
join _plat pl on pl.slug = p.slug
join _tpl t on t.typ = pl.typ
where g.platform_id = p.id;

drop table _plat;
drop table _tpl;
