insert into public.ai_platforms (slug, name, short_description, category, official_url, verification_status, kenya_eligibility, last_verified, is_featured) values
  ('surge-ai', 'Surge AI', 'Human data company that supplies labeling and evaluation data to AI labs. It runs the DataAnnotation platform for contributors.', 'ai_training', 'https://surgehq.ai', 'under_review', 'unknown', null, false),
  ('scale-ai', 'Scale AI', 'AI data company. Contributor work is run through its Outlier platform; Remotasks was its earlier task platform.', 'data_annotation', 'https://scale.com', 'under_review', 'unknown', null, false),
  ('snorkel-ai', 'Snorkel AI', 'Data development company that works with expert contributors to build specialised datasets for AI models.', 'expert_freelancing', 'https://snorkel.ai', 'under_review', 'unknown', null, false),
  ('pareto-ai', 'Pareto.AI', 'Data labeling and AI training company that works with contributors on text, audio and image projects.', 'ai_training', 'https://pareto.ai', 'under_review', 'unknown', null, false),
  ('perle', 'Perle', 'AI data company that works with domain experts on training and evaluation data.', 'expert_freelancing', 'https://www.perle.ai', 'under_review', 'unknown', null, false),
  ('sapien', 'Sapien', 'Data labeling platform with a contributor network that produces training data for AI models.', 'data_annotation', 'https://www.sapien.io', 'under_review', 'unknown', null, false),
  ('braintrust', 'Braintrust', 'Talent marketplace where freelancers apply to technology and AI projects.', 'expert_freelancing', 'https://www.usebraintrust.com', 'under_review', 'unknown', null, false),
  ('toptal', 'Toptal', 'Selective freelance network for software engineers, designers and finance experts, including AI and machine-learning specialists.', 'expert_freelancing', 'https://www.toptal.com', 'under_review', 'unknown', null, false),
