insert into public.ai_platform_guides (platform_id)
insert into _tpl values
  ('llm', 'Applications are made on the platform''s own website. Availability depends on open projects, your skills and your country.', 'Work is usually project-based: you qualify through a screening step and are then invited to tasks such as writing prompts and responses, rating and comparing model outputs, or checking facts.', array['Computer or laptop with an up-to-date browser','Stable internet connection'], array['Strong written English (or another supported language)','Careful reading and following detailed guidelines','Subject knowledge for specialist projects'], array['Valid email address you control','Accurate profile and work or education details','Identity verification may be requested','A payout method the platform supports in your country'], 'Most platforms of this type screen applicants with a skills test or sample tasks before any paid work. Exact tests vary by project.', 'Read the instructions fully before you start. Tests are often timed and some can be attempted only once. Do not use AI tools or outside help unless the instructions say you may.', 'Pay is set by the platform and the project. Do not rely on example hourly rates in adverts or videos. Work can be irregular, and projects can end without warning.', 'Payout methods, minimums and fees were not independently verified. Check the platform''s payments help pages and confirm that a payout route works for your country before you invest time.', array['Open the platform''s official website by typing the address yourself. Do not follow ads, DMs or links from strangers.','Choose the contributor or apply option that matches your skills.','Create your account with your real name and an email address only you control.','Complete your profile and any identity check honestly.','Take the screening test or sample tasks and wait for the result.','Read each project''s guidelines before accepting tasks.'], array['Registering from a different country than where you live, or using a VPN.','Rushing the screening test without reading the guidelines.','Paying anyone for ''guaranteed'' access or buying a verified account.','Assuming steady work: projects open and close.'], array['Prepare a clean, accurate profile before you apply.','Confirm the payout route for your country early.','Keep records of tasks completed and payments received.']),
  ('crowd', 'Registration is handled on the platform''s own website. Platforms of this type often open and close sign-ups by country depending on demand.', 'Work is made of short tasks, such as labeling images or text, checking data, transcription or surveys. You usually qualify through short tests and then pick tasks from a queue.', array['Computer or smartphone, depending on the task','Stable internet connection'], array['Attention to detail','Reading and following task instructions','Language skills for language tasks'], array['Valid email address you control','Accurate personal and profile details','Identity or phone verification may be requested','A supported payout method'], 'Many task platforms require qualification tests or training before higher-paid tasks unlock. Details vary by platform and project.', 'Accuracy scores often decide which tasks you can see. Work carefully and keep one account only: duplicate accounts are commonly banned.', 'Task pay is usually low per task and varies widely. Do not rely on example earnings. Task supply can be uneven.', 'Payout methods, minimums and fees were not independently verified. Check which methods appear in your account before you start.', array['Open the platform''s official website by typing the address yourself.','Choose the worker or contributor sign-up.','Create one account with your real details and an email only you control.','Complete your profile, language and skill sections honestly.','Finish the qualification tests or training offered.','Start with the tasks you are qualified for and read each task''s instructions.'], array['Creating more than one account.','Using a VPN or another country''s details to register.','Skipping task instructions and losing your accuracy score.','Paying a third party to ''unlock'' an account.'], array['Confirm that your country can register and be paid before you start.','Treat it as variable side income, not a salary.','Withdraw earnings when you reach the minimum so money is not stuck.']),
  ('vendor', 'Opportunities are listed on the company''s own careers or community pages. Openings depend on the project, your country and your language.', 'Work is delivered through the company''s contributor community or project teams, covering tasks such as data collection, annotation, rating and language work. Some roles are freelance and some are employed teams.', array['Computer or laptop with an up-to-date browser','Stable internet connection','Headset or smartphone for audio and voice projects'], array['Attention to detail','Fluency in the language of the project','Ability to follow detailed guidelines'], array['Valid email address you control','CV or profile details','Identity verification may be requested','A supported payout method or contract details'], 'Applicants are often asked to pass language, skills or qualification tests for a specific project. Details vary.', 'Read the project description closely. Many tests are specific to one project and openings can close quickly.', 'Pay depends on the project and role. Do not rely on example rates from third-party sites. Some contributors are paid per task and some per hour.', 'Payment methods and schedules were not independently verified. The company or project will state them in its onboarding documents.', array['Find the company''s official community or careers page and open it by typing the address yourself.','Browse open projects or join the contributor community.','Create an account with your real details.','Complete the profile, language and identity steps.','Pass any qualification test for the project.','Read the onboarding documents and payment terms before you start work.'], array['Applying through unofficial recruiters or social-media offers that ask for a fee.','Overstating your language level in the profile.','Ignoring the contract or payment terms.'], array['Apply only through the company''s own pages.','Keep your CV and profile consistent with your answers in tests.','Ask for payment terms in writing if they are not clear.']),
  ('expert', 'Applications are made on the platform''s own website. Acceptance depends on your background, the projects open and the country rules.', 'The platform places skilled people, such as developers, subject-matter experts and professionals, on AI training, evaluation and technology projects. Applicants are usually screened with an interview, test or review of their background.', array['Computer or laptop with an up-to-date browser','Webcam and microphone for interviews','Stable internet connection'], array['Professional or subject expertise','Clear written and spoken English','Reliability and deadline discipline'], array['Valid email address you control','CV or LinkedIn profile','Identity and work-eligibility checks may be requested','A supported payout method'], 'Screening may include an AI-led or live interview, a coding or subject test and a background review. Details vary.', 'Prepare as for a job interview. Keep your claimed experience accurate: it is usually checked.', 'Rates are set per project or contract and are not guaranteed. Do not rely on rates quoted by third-party sites.', 'Payout methods and country coverage were not independently verified. Check the platform''s payments and supported-countries pages before you invest time.', array['Open the platform''s official website by typing the address yourself.','Choose the expert or talent application.','Create your account and upload an accurate CV or profile.','Complete identity verification if asked.','Take the interview or skills test.','Review any contract and payout terms before accepting a project.'], array['Applying from an unsupported country or using a VPN.','Overstating experience in the profile or interview.','Accepting work before confirming how you will be paid.','Paying a recruiter for ''guaranteed'' placement.'], array['Check the platform''s supported-countries list first.','Keep your profile and interview answers consistent.','Never pay to be considered for work.']),
  ('market', 'Registration is made on the platform''s own website. Profile approval, country rules and fees depend on the platform.', 'A marketplace where you create a profile and either bid on projects or list services. Clients pay through the platform, which usually takes a fee.', array['Computer or laptop','Stable internet connection','Portfolio samples or work history'], array['A skill clients will pay for','Clear communication in English','Time management and deadline discipline'], array['Valid email address you control','Accurate profile and portfolio','Identity verification is commonly required','A supported payout method'], 'There is no single test, but profile approval, skills tests or vetting may apply. Competition for projects can be high.', 'Your profile, portfolio and reviews decide how many clients you reach. Start with a clear niche.', 'Earnings depend on your skill, niche and reviews. Platform fees reduce what you receive. Do not rely on example earnings.', 'Payout methods, fees and minimums were not independently verified. Check the platform''s payments help before you start and compare withdrawal options for Kenya.', array['Open the platform''s official website by typing the address yourself.','Sign up as a freelancer or seller.','Complete your profile with an honest summary, skills and portfolio.','Complete identity verification if asked.','Set up a payout method.','Apply for projects or publish your first service.'], array['Buying or borrowing an established account.','Taking payment or communication outside the platform.','Using fake reviews or someone else''s portfolio.'], array['Pick a narrow niche you can deliver well.','Read the fee schedule before pricing your work.','Keep all communication and payment inside the platform.']),
  ('board', 'Free to browse. Applications are made to the employer named in each listing.', 'A job board or aggregator. You search listings and apply to employers; the board itself usually does not hire you or pay you.', array['Computer or smartphone','Stable internet connection','Up-to-date CV'], array['A CV tailored to each role','Clear written English','Ability to spot fake or misleading listings'], array['Email address you control','A CV or profile','Some employers require tests or interviews'], 'Depends on each employer. Expect application forms, tests or interviews.', 'Each employer sets its own screening. Check the employer''s own website before you apply.', 'The board does not pay you. Pay is set by each employer.', 'Not applicable to the board itself. Payment terms come from each employer or platform.', array['Open the board''s official website by typing the address yourself.','Create a profile and upload your CV if the site offers it.','Search for roles and filter by remote and country.','Open the employer''s own page to confirm the role is real.','Apply following the employer''s instructions.','Prepare for any test or interview.'], array['Paying a fee to apply or to ''secure'' a role.','Sharing ID or bank details before a real contract exists.','Applying to roles that restrict your country.'], array['Confirm every listing on the employer''s own site.','Check whether the role accepts applicants from your country.','Treat requests for upfront payment as a scam.']),
  ('comp', 'Registration is free or open on the platform''s own website. Each competition or programme has its own rules and eligibility.', 'You take part in competitions, bounties or challenges. You usually earn prizes or rewards based on rankings or accepted findings rather than a regular wage.', array['Computer or laptop','Stable internet connection','Relevant tools such as Python or security testing tools'], array['Programming, data science or security skills','Persistence and independent problem solving','Reading competition rules carefully'], array['Email address you control','A profile on the platform','Acceptance of each competition''s rules','Prize eligibility and payout details may be required'], 'There is no hiring test. Your work is judged by the competition''s scoring, leaderboard or program rules.', 'Read each competition''s eligibility and prize rules. Some restrict prizes by country or residence.', 'Income is irregular and can be zero. Only top results or accepted findings are paid. Do not count on prizes as income.', 'Prize payment methods and country coverage differ by competition. Check each competition''s rules before you enter.', array['Open the platform''s official website by typing the address yourself.','Create a free profile.','Browse open competitions or programmes and read the rules.','Check that you are eligible for prizes where you live.','Download the data or scope and start work.','Submit before the deadline and follow the payout instructions.'], array['Entering without checking prize eligibility for your country.','Ignoring submission rules or deadlines.','Violating a programme''s scope or terms, which can disqualify you or cause legal problems.'], array['Start with beginner or learning competitions.','Treat prizes as a bonus, not income.','Stay strictly inside each programme''s scope and rules.']),
  ('comm', 'Open through the organisation''s own website. Programmes, calls and funding rounds are announced periodically.', 'A community, research group or funding body. Participation is often voluntary or grant-based rather than a paid job, though it can lead to experience, networks and opportunities.', array['Computer or smartphone','Stable internet connection'], array['Interest or skills in AI, data or languages','Willingness to collaborate','Ability to commit time without guaranteed pay'], array['Email address you control','Sign-up on the organisation''s website','Applications for grants or fellowships may need a proposal or CV'], 'Usually none for joining. Grants and fellowships use an application and review process.', 'Read each call for applications fully. Funding rounds have deadlines and eligibility rules.', 'Participation may not be paid. Where grants or paid roles exist, the organisation states the amounts.', 'Not independently verified. Check each programme''s call or role description for any payment.', array['Open the organisation''s official website by typing the address yourself.','Read what the community or programme does and who can join.','Create an account or join the mailing list or forum.','Introduce yourself and look for open projects or calls.','Contribute where you can add value.','Apply to any funded programmes that match your profile.'], array['Expecting a regular income from voluntary participation.','Ignoring the contribution or data licensing rules.','Missing application deadlines.'], array['Use it to build experience, a portfolio and contacts.','Check each call''s eligibility before you apply.','Do not pay to join a community that claims to guarantee jobs.']),
  ('lang', 'Applications are made on the company''s own site or vendor portal. Openings depend on your language pair and subject area.', 'A language services company or marketplace that works with freelance translators, linguists and reviewers, including on machine-translation and AI language data projects.', array['Computer or laptop','Stable internet connection','Translation or CAT tools if the project requires them'], array['Native or near-native skills in your target language','Strong command of the source language','Translation, proofreading or subject experience'], array['Email address you control','CV with language pairs and experience','Translation or language test','Invoicing or payout details'], 'Applicants are normally tested with a translation or review sample in their language pair.', 'Prepare samples in your strongest subject area. Quality scores affect how much work you get.', 'Rates are per word, per hour or per project and are set by the company or you. Do not rely on rates from third-party sites.', 'Payment methods and invoicing terms were not independently verified. Agree them in writing before accepting work.', array['Open the company''s official website by typing the address yourself.','Go to the translators, linguists or vendors section.','Submit your CV with your language pairs and subject areas.','Complete the translation or review test.','Complete vendor onboarding and tax or payout details.','Accept projects that fit your language pair and deadline.'], array['Listing language pairs you cannot work in at professional quality.','Using unreviewed machine translation without declaring it.','Accepting work without agreeing rates and payment dates.'], array['Build a small portfolio of translation samples.','Apply to several vendors since work is irregular.','Agree rates and payment terms before starting.']),
  ('trans', 'Applications are made on the company''s own website, usually with a short test.', 'A transcription, captioning or subtitling service that uses freelance transcribers or reviewers. Work involves listening to audio or video and producing accurate text.', array['Computer or laptop','Good headphones','Stable internet connection','Foot pedal or transcription software if the company recommends it'], array['Strong listening and typing skills','Excellent English or target-language grammar','Attention to detail and consistency with style guides'], array['Email address you control','Accurate profile','Transcription test','A supported payout method, often PayPal or bank transfer (not independently verified)'], 'Applicants typically complete a transcription or review test. Failing the test may mean waiting before you can retry.', 'Read the style guide before the test. Accuracy and following the style guide matter more than speed.', 'Pay is usually per audio minute or per task and varies by difficulty. Do not rely on third-party rate claims.', 'Payout schedule, methods and minimums were not independently verified. Check the company''s help pages.', array['Open the company''s official website by typing the address yourself.','Find the transcriber or contributor application.','Create your account with accurate details.','Take the transcription test.','Read the style guide and onboarding material.','Pick up available files and submit work on time.'], array['Poor audio setup that causes errors.','Ignoring the style guide.','Missing deadlines, which can reduce access to work.'], array['Use good headphones and a quiet room.','Study the style guide before every project.','Keep accuracy high to unlock better-paying files.']),
  ('creator', 'Open registration on the platform''s own website, subject to content review and country and payout rules.', 'A marketplace or programme where you sell or license content or creative assets such as images, prompts or voice. Earnings depend on sales or usage rather than a wage.', array['Computer or smartphone','Camera or creative tools for your content','Stable internet connection'], array['Ability to produce original, high-quality content','Understanding of licensing and releases','Keywords, titles and descriptions'], array['Email address you control','Identity and tax information where required','Original content you have the right to license','A supported payout method'], 'Content is reviewed for quality and rights. Some platforms ask for sample uploads first.', 'Only upload content you created and have rights to. Read the platform''s rules on AI-generated content and AI training use.', 'Income depends on how often your content is bought or used. Many contributors earn little. Do not rely on example earnings.', 'Payout methods, thresholds and tax forms were not independently verified. Check the contributor help pages.', array['Open the platform''s official website by typing the address yourself.','Create a contributor or creator account.','Complete identity and payout setup.','Read the content and licensing rules, including rules on AI content.','Upload a small first batch of original work.','Wait for review and improve based on feedback.'], array['Uploading content you do not own or that contains logos, people or property without releases.','Ignoring rules on AI-generated or AI-trained content.','Not checking payout thresholds and tax rules.'], array['Start with a few high-quality items.','Read what rights you grant when you upload.','Check payout availability for Kenya before investing time.']),
  ('prog', 'Programme details and registration are on the official programme website and through local centres.', 'A government programme that offers training, mentorship and links to online work. It is not an employer and does not guarantee jobs.', array['Smartphone or computer','Internet access'], array['Willingness to learn digital skills','Self-discipline for online work'], array['Email address or phone number','Registration on the programme site or at a local centre'], 'No hiring test. Training may have its own enrolment steps.', 'Use it to learn digital skills and to find legitimate online platforms. Always confirm each platform''s rules separately.', 'The programme does not pay wages. Earnings come from the online work you later find.', 'Not applicable. The programme itself does not pay contributors.', array['Open the programme''s official website by typing the address yourself.','Read who can register and what training is offered.','Register on the website or at a local centre.','Complete the training modules that match your goals.','Use the platform guidance to find online work.','Apply to platforms that accept applicants from your country.'], array['Paying anyone for a ''guaranteed job'' linked to the programme.','Assuming the programme will find you work.'], array['Use it for skills and networking.','Confirm each work platform''s rules before you rely on it.']);
