  ('brightermonday-kenya', 'BrighterMonday Kenya', 'board', 'Kenyan job board with local and some remote listings.', 'https://www.brightermonday.co.ke', 'unknown', 'unknown', null, ' Savanna lists this as Kenya-relevant, but confirm the details on its own pages.', null),
